  let filtered=checks.filter(c=>(photoCheckFilter==='all'||c.status===photoCheckFilter)&&(c.group+' '+c.title+' '+c.location+' '+c.source+' '+c.why).toLowerCase().includes(photoCheckQuery.toLowerCase()));
