function openMobileCaptureFolder(){openForm('mobileCaptureFolder');$('#entryForm button[type=submit]').textContent='次へ：カメラ撮影';let board=items('blackboards').find(b=>b.id===mobileCaptureFlow.boardId);$('#mobileBoardSummary').textContent=board?'使用する黒板：'+board.name:'黒板を使用しない';$('#mobileCaptureFolderSelect').innerHTML='<option value="" disabled selected>保存先を選択</option><option value="none">未分類</option>'+items('photoFolders').map(f=>`<option value="${esc(f.id)}">${esc(folderPath(f))}</option>`).join('')}
function syncMobileCameraHud(){let hud=$('#mobileCameraHud');if(!hud||!mobileCaptureFlow||formType!=='photo')return;let shot=!!capturedPhotoData||!!$('#entryForm [name=file]')?.files?.length,live=!!photoCameraStream&&!$('#photoCameraVideo')?.hidden;let shutter=$('[data-mobile-shutter]'),retake=$('[data-mobile-retake]'),save=$('[data-mobile-save]');shutter.hidden=shot;shutter.disabled=!live;retake.hidden=!shot;save.disabled=!shot}
function openMobileCaptureCamera(){openForm('photo');$('#modal').classList.add('mobile-capture-mode');$('#modalTitle').textContent='写真撮影 · 3/3 カメラ撮影';$('#photoFolderSelect').value=mobileCaptureFlow.folderId==='none'?'':mobileCaptureFlow.folderId;$('#boardSelect').value=mobileCaptureFlow.boardId;if(mobileCaptureFlow.boardId&&$('#boardSelect').value!==mobileCaptureFlow.boardId){alert('黒板が見つかりません。選び直してください');openMobileCaptureBoard();return}showSelectedBoardFields();let board=items('blackboards').find(b=>b.id===mobileCaptureFlow.boardId),folder=items('photoFolders').find(f=>f.id===mobileCaptureFlow.folderId);$('#entryForm').insertAdjacentHTML('afterbegin',`<div id="mobileCameraHud"><div class="mobile-camera-top"><button type="button" data-mobile-back aria-label="保存フォルダー選択に戻る">‹</button><div><strong>写真撮影</strong><small>黒板：${esc(board?.name||'なし')}　保存先：${esc(folder?folderPath(folder):'未分類')}</small></div><button type="button" data-mobile-close aria-label="写真撮影を終了">×</button></div><div class="mobile-camera-bottom"><button type="button" data-mobile-options>写真・日付</button><button type="button" class="mobile-shutter" data-mobile-shutter aria-label="写真を撮影" disabled><span></span></button><button type="button" data-mobile-retake hidden>撮り直し</button><button type="button" data-mobile-save disabled>保存</button></div></div><div id="mobileCameraExtras" hidden></div>`);let extras=$('#mobileCameraExtras'),file=$('#entryForm [name=file]');file.removeAttribute('capture');extras.append(file.closest('label'),$('#entryForm [name=date]').closest('label'));$('#entryForm button[type=submit]').textContent='写真を保存';$('#entryForm button[type=submit]').disabled=true;syncMobileCameraHud();$('#photoCameraStatus').textContent='カメラを準備しています…';let start=$('[data-camera-start]');start.textContent='カメラを起動';startPhotoCamera()}
$('#mobileCaptureLauncher').addEventListener('click',openMobileCaptureBoard);
document.addEventListener('change',e=>{if(e.target.name==='useBoard'&&formType==='mobileCaptureBoard'){$('#mobileBoardPicker').hidden=e.target.value!=='yes';if(e.target.value==='yes'){$('#boardSelect').value='';showSelectedBoardFields()}}if(formType==='photo'&&mobileCaptureFlow&&e.target.matches('#entryForm [name=file]')&&e.target.files?.length){stopPhotoCamera();capturedPhotoData='';clearMobileFilePreview();mobileSelectedFileUrl=URL.createObjectURL(e.target.files[0]);$('#photoCameraStill').src=mobileSelectedFileUrl;$('#photoCameraStill').hidden=false;$('#photoCameraVideo').hidden=true;$('#photoCameraStage').hidden=false;$('#photoCameraStatus').textContent='写真を選択しました。保存するか、撮り直してください。';$('#entryForm button[type=submit]').disabled=false;syncMobileCameraHud()}});
document.addEventListener('click',e=>{if(e.target.closest('[data-mobile-go-boards]')){closeForm();page='photos';photoView='boards';render();openForm('board');return}if(!e.target.closest('[data-mobile-back]'))return;if(formType==='photo'&&mobileCaptureFlow){stopPhotoCamera();$('#modal').classList.remove('mobile-capture-mode');openMobileCaptureFolder();$('#mobileCaptureFolderSelect').value=mobileCaptureFlow.folderId}else if(formType==='mobileCaptureFolder'&&mobileCaptureFlow){let selected=mobileCaptureFlow.boardId;openForm('mobileCaptureBoard');$('#entryForm button[type=submit]').textContent='次へ：保存フォルダー';populateBoardPicker();$('#entryForm [name=useBoard][value="'+(selected?'yes':'no')+'"]').checked=true;$('#mobileBoardPicker').hidden=!selected;$('#boardSelect').value=selected;showSelectedBoardFields()}});
$('#entryForm').addEventListener('submit',e=>{if(!['mobileCaptureBoard','mobileCaptureFolder'].includes(formType))return;e.preventDefault();e.stopImmediatePropagation();if(formType==='mobileCaptureBoard'){let form=new FormData(e.currentTarget),choice=form.get('useBoard');if(!choice)return alert('黒板の有無を選択してください');let id=choice==='yes'?String(form.get('boardId')||''):'';if(choice==='yes'&&!items('blackboards').some(b=>b.id===id))return alert('使用する黒板を選択してください。黒板がない場合は先に作成してください。');mobileCaptureFlow.boardId=id;openMobileCaptureFolder()}else{let folderId=String(new FormData(e.currentTarget).get('folderId')||'');if(!folderId||folderId!=='none'&&!items('photoFolders').some(f=>f.id===folderId))return alert('保存フォルダーを選択してください');mobileCaptureFlow.folderId=folderId;openMobileCaptureCamera()}},true);

document.addEventListener('click',e=>{let button=e.target.closest('[data-mobile-shutter],[data-mobile-retake],[data-mobile-save],[data-mobile-options],[data-mobile-close]');if(!button||!mobileCaptureFlow||formType!=='photo')return;if(button.hasAttribute('data-mobile-close')){closeForm();return}if(button.hasAttribute('data-mobile-options')){$('#mobileCameraExtras').hidden=!$('#mobileCameraExtras').hidden;return}if(button.hasAttribute('data-mobile-shutter')){if(!button.disabled)$('[data-camera-capture]').click();return}if(button.hasAttribute('data-mobile-retake')){capturedPhotoData='';clearMobileFilePreview();$('#entryForm [name=file]').value='';$('#photoCameraStill').hidden=true;$('#photoCameraStage').hidden=true;$('#entryForm button[type=submit]').disabled=true;$('#mobileCameraExtras').hidden=true;syncMobileCameraHud();startPhotoCamera();return}if(button.hasAttribute('data-mobile-save')&&!button.disabled){$('#entryForm').requestSubmit($('#entryForm button[type=submit]'))}});

fields.companyProfile={title:'会社情報を登録・編集',html:'<label class="field">会社名<input name="name" required maxlength="100" placeholder="例：株式会社ダイトク"></label><label class="field">連絡先・メモ<input name="contact" maxlength="120" placeholder="会社の代表連絡先など"></label>'};
fields.userProfile={title:'ユーザー情報を登録',html:'<label class="field">氏名<input name="name" required maxlength="80"></label><label class="field">所属会社・協力会社<input name="affiliation" maxlength="100"></label><label class="field">メール<input type="email" name="email" maxlength="120"></label><label class="field">電話<input type="tel" name="phone" maxlength="40"></label><label class="field">役割<select name="role"><option>会社管理者</option><option>現場管理者</option><option selected>担当者</option><option>閲覧者</option></select></label><fieldset class="user-site-choices"><legend>所属現場と階層（複数選択可）</legend><div id="userProjectChoices"></div></fieldset><p class="hint">役割は現在、担当を整理するための表示項目です。</p>'};
let editingUserId='';
function openUserProfile(id=''){let user=data.users.find(u=>u.id===id);editingUserId=user?.id||'';openForm('userProfile');$('#modalTitle').textContent=user?'ユーザー情報を編集':'ユーザー情報を登録';if(user)for(let key of ['name','affiliation','email','phone','role'])$(`#entryForm [name=${key}]`).value=user[key]||'';$('#userProjectChoices').innerHTML=data.projects.length?data.projects.map(p=>`<div class="user-project-entry"><label><input type="checkbox" name="projectId" value="${esc(p.id)}" ${(user?.projectIds||[]).includes(p.id)?'checked':''}> ${esc(p.name)}</label><div class="user-role-options">${['現場管理者','担当者','閲覧者'].map(role=>`<label><input type="checkbox" name="siteRole:${esc(p.id)}" value="${role}" ${(user?.siteRoles?.[p.id]||((user?.projectIds||[]).includes(p.id)?[user?.role==='会社管理者'?'現場管理者':user?.role||'担当者']:[])).includes(role)?'checked':''}> ${role}</label>`).join('')}</div></div>`).join(''):'<p class="hint">現場がまだありません。現場管理から先に登録できます。</p>'}
$('#profileButton').addEventListener('click',()=>{page='users';render()});
document.addEventListener('click',e=>{let el=e.target.closest('[data-company-edit],[data-user-add],[data-user-edit],[data-user-delete],[data-user-active]');if(!el)return;if(el.hasAttribute('data-company-edit')){openForm('companyProfile');$('#entryForm [name=name]').value=data.companyProfile.name||'';$('#entryForm [name=contact]').value=data.companyProfile.contact||'';return}if(el.hasAttribute('data-user-add')){openUserProfile();return}if(el.hasAttribute('data-user-edit')){openUserProfile(el.dataset.userEdit);return}if(el.hasAttribute('data-user-active')){let user=data.users.find(u=>u.id===el.dataset.userActive);if(!user)return;let old=data.activeUserId;data.activeUserId=user.id;if(!save()){data.activeUserId=old;return}render();return}if(el.hasAttribute('data-user-delete')){let user=data.users.find(u=>u.id===el.dataset.userDelete);if(!user||!confirm(`「${user.name}」のユーザー情報を削除しますか？`))return;let old=data.users,oldActive=data.activeUserId;data.users=old.filter(u=>u.id!==user.id);if(data.activeUserId===user.id)data.activeUserId='';if(!save()){data.users=old;data.activeUserId=oldActive;return}render()}});
$('#entryForm').addEventListener('submit',e=>{if(formType!=='companyProfile'&&formType!=='userProfile')return;e.preventDefault();e.stopImmediatePropagation();let f=new FormData(e.currentTarget);if(formType==='companyProfile'){let name=String(f.get('name')||'').trim();if(!name)return alert('会社名を入力してください');let old=data.companyProfile;data.companyProfile={name,contact:String(f.get('contact')||'').trim()};if(!save()){data.companyProfile=old;return}}else{let name=String(f.get('name')||'').trim(),role=String(f.get('role')||'担当者'),projectIds=f.getAll('projectId').map(String).filter(id=>data.projects.some(p=>p.id===id));if(!name)return alert('氏名を入力してください');if(!['会社管理者','現場管理者','担当者','閲覧者'].includes(role))return alert('役割を選択してください');if(role!=='会社管理者'&&!projectIds.length)return alert('所属現場を1つ以上選択してください');let old=data.users,oldActive=data.activeUserId,previous=old.find(u=>u.id===editingUserId),user={id:previous?.id||uid(),name,affiliation:String(f.get('affiliation')||'').trim(),email:String(f.get('email')||'').trim(),phone:String(f.get('phone')||'').trim(),role,projectIds,siteRoles:Object.fromEntries(projectIds.map(id=>[id,f.getAll(`siteRole:${id}`).map(String).filter(x=>['現場管理者','担当者','閲覧者'].includes(x))]).map(([id,roles])=>[id,roles.length?roles:[role==='会社管理者'?'現場管理者':role]]))};data.users=previous?old.map(u=>u.id===previous.id?user:u):[...old,user];if(!data.activeUserId)data.activeUserId=user.id;if(!save()){data.users=old;data.activeUserId=oldActive;return}}editingUserId='';closeForm();render()},true);
